const fs=require('fs');
const {art}=require('./art3');const CFG=require('./config');
const BASE='/calisthenics-comics',SITE='https://brenohildebrand.github.io'+BASE,TODAY=new Date().toISOString().slice(0,10);
const slug=s=>s.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
const esc=s=>String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
const tier=d=>d<=2?'Rookie':d<=4?'Brawler':d<=6?'Hero':d<=8?'Champion':d==9?'Titan':'Legend';
const CAT={push:['Push','#ff3b3b','Push movements build chest, shoulders and triceps — from wall push-ups to the planche push-up.'],pull:['Pull','#2f6bff','Pull movements build lats, biceps and grip — from dead hangs to the one-arm pull-up and muscle-up.'],legs:['Legs','#18b85a','Bodyweight leg training: squats, lunges, pistols and Nordic curls for strong, springy legs.'],core:['Core','#ffb800','Core work from dead bugs to dragon flags and the manna — the foundation of every skill.'],skills:['Skills','#a43bff','Calisthenics skills: handstands, levers, planches and the human flag. The boss fights.']};
const HOLDS=new Set(['dead-hang','plank','side-plank','hollow-body-hold','arch-body-hold','wall-sit','l-sit','v-sit','manna','handstand-wall-hold','crow-pose','freestanding-handstand','one-arm-handstand','elbow-lever','frog-stand','tuck-planche','straddle-planche','full-planche','tuck-front-lever','straddle-front-lever','full-front-lever','back-lever','human-flag','bridge']);
const M=require('./data.js').map(([name,cat,muscles,diff,w,how,e,h])=>({name,slug:slug(name),cat,muscles,diff,tier:tier(diff),weighted:!!w,weightHow:w,how,easier:e?slug(e):'',harder:h?slug(h):''}));
const by=Object.fromEntries(M.map(m=>[m.slug,m]));
for(const m of M)for(const k of['easier','harder'])if(m[k]&&!by[m[k]])throw 'bad link '+m.name;
const MIST={push:['Flaring elbows straight out to 90° — keep them around 45° to protect the shoulders.','Sagging hips or piking up — squeeze glutes and brace like a plank.','Cutting the range short — go all the way down and lock out at the top.','Pushing the head forward instead of moving the whole body as one unit.'],
pull:['Kipping or swinging to cheat reps — pause in the dead hang between reps.','Half reps — start from straight arms and finish with the chin (or chest) over the bar.','Shrugging into the ears — pull the shoulder blades down and back first.','Skipping grip and scapular work, which limits every pulling skill.'],
legs:['Knees caving inward — push them out in line with the toes.','Heels lifting off the floor — sit back and keep weight mid-foot.','Dropping fast with no control — own the lowering phase.','Rounding the lower back at the bottom.'],
core:['Arching the lower back — keep it pressed toward the floor (posterior pelvic tilt).','Holding your breath — breathe shallow and keep the brace.','Using momentum instead of control.','Chasing long, sloppy holds instead of short, perfect ones.'],
skills:['Bending the arms on straight-arm skills — lock the elbows and train the tendons slowly.','Rushing to the next progression before owning the current one.','Skipping wrist and shoulder warm-ups.','Training to failure every session — skills love fresh, frequent practice.']};
const plan=m=>{const H=HOLDS.has(m.slug),d=m.diff;const r=d<=2?[H?'3 × 20–30 s holds':'3 × 10–15 reps','60 s','3×/week']:d<=4?[H?'3–4 × 15–30 s holds':'3–4 × 8–12 reps','90 s','3×/week']:d<=6?[H?'4–5 × 10–20 s holds':'4 × 5–8 reps','2 min','2–3×/week']:d<=8?[H?'5–6 × 5–10 s holds':'5 × 3–5 reps','2–3 min','2–3×/week']:[H?'6–8 × 3–6 s holds':'5–8 × 1–3 reps (singles welcome)','3 min','2×/week'];
 return {scheme:r[0],rest:r[1],freq:r[2],goal:H?(d>=7?'Hold 10–15 s clean':'Hold 30–60 s clean'):(d>=7?'3 × 5 clean reps':'3 × 12–15 clean reps')}};
const chain=m=>{const down=[],up=[];let x=m;const seen=new Set([m.slug]);while(x.easier&&!seen.has(x.easier)){x=by[x.easier];seen.add(x.slug);down.unshift(x)}x=m;while(x.harder&&!seen.has(x.harder)){x=by[x.harder];seen.add(x.slug);up.push(x)}return[...down,m,...up]};
const GOALS=[['full-planche','Full Planche'],['full-front-lever','Front Lever'],['back-lever','Back Lever'],['human-flag','Human Flag'],['muscle-up','Muscle-Up'],['one-arm-pull-up','One-Arm Pull-Up'],['one-arm-push-up','One-Arm Push-Up'],['planche-push-up','Planche Push-Up'],['freestanding-handstand','Handstand'],['freestanding-handstand-push-up','Handstand Push-Up'],['pistol-squat','Pistol Squat'],['dragon-flag','Dragon Flag'],['manna','Manna']];
const roadOf=g=>{const c=[by[g]];let x=by[g];const seen=new Set([g]);while(x.easier&&!seen.has(x.easier)){x=by[x.easier];seen.add(x.slug);c.unshift(x)}return c};
const ROADS=GOALS.map(([g,label])=>({g,label,steps:roadOf(g)}));
const PLANS=[{id:'beginner',label:'Beginner',band:'Levels 1–3',og:'incline-push-up',days:'3 days a week on non-consecutive days (for example Monday, Wednesday and Friday)',time:'about 40–50 minutes',who:'You are new to training or coming back after a long break. You may not have a pull-up yet, and that is fine.',moves:['dead-hang','incline-push-up','australian-row','bodyweight-squat','lunge','glute-bridge','plank','dead-bug'],next:'You can do 3 × 12 clean push-ups, 3 × 8 negative pull-ups and a 60-second plank.'},
{id:'intermediate',label:'Intermediate',band:'Levels 3–6',og:'pull-up',days:'3–4 days a week, with at least one rest day between hard sessions',time:'about 60–75 minutes',who:'You can do a few strict pull-ups and around 15 push-ups, and want to build real strength and your first skills.',moves:['handstand-wall-hold','pull-up','parallel-bar-dip','pike-push-up','australian-row','bulgarian-split-squat','cossack-squat','hanging-knee-raise','hollow-body-hold'],next:'You can do 3 × 10 pull-ups, 3 × 12 dips, a 30-second wall handstand and a 30-second hollow hold.'},
{id:'advanced',label:'Advanced',band:'Levels 5–8',og:'freestanding-handstand',days:'4 days a week, with skill work at the start of every session while you are fresh',time:'about 80–100 minutes (pair a push move with a pull move as supersets to bring it closer to an hour)',who:'You own the basics (10+ pull-ups, 12+ dips) and are chasing levers, handstands and single-leg strength.',moves:['freestanding-handstand','tuck-front-lever','chest-to-bar-pull-up','ring-dip','archer-push-up','pistol-squat','nordic-curl','hanging-leg-raise','l-sit'],next:'You own every move here for its level-up goal. Pick a boss move from the skill roadmaps and specialise.'}];
const MUS=[{id:'chest',label:'Chest',re:/chest/i,og:'push-up',why:'A strong chest comes from pressing: push-ups and dips first, then leaning further forward into planche work.'},
{id:'back',label:'Back',re:/lats|upper back|mid back|teres|traps|rear delts|lower back/i,og:'pull-up',why:'Your back is built by pulling your body to a bar or rings, from rows and hangs to front levers and the one-arm pull-up.'},
{id:'shoulders',label:'Shoulders',re:/shoulder|delts/i,og:'pike-push-up',why:'Shoulders grow from overhead pressing and straight-arm holds: pike push-ups, handstands and planche leans.'},
{id:'biceps',label:'Biceps',re:/biceps/i,og:'chin-up',why:'Bodyweight biceps work means chin-ups, rows and straight-arm skills like the back lever that load the biceps tendons.'},
{id:'triceps',label:'Triceps',re:/triceps/i,og:'diamond-push-up',why:'Triceps do the lockout on every press: close-grip push-ups, dips and handstand push-ups train them hard.'},
{id:'abs',label:'Abs & Core',re:/core|abs|oblique|anterior chain/i,og:'hollow-body-hold',why:'Calisthenics core work is about bracing and control, from planks and dead bugs to L-sits, dragon flags and the manna.'},
{id:'glutes',label:'Glutes',re:/glute/i,og:'glute-bridge',why:'Glutes respond to hip extension and single-leg work: bridges, lunges, split squats and pistols.'},
{id:'quads',label:'Quads',re:/quads/i,og:'bodyweight-squat',why:'Quads are built with deep knee bends: squats, split squats, sissy squats and the pistol.'},
{id:'grip',label:'Grip & Forearms',re:/grip|forearm|wrist/i,og:'dead-hang',why:'Grip and wrist strength is the hidden limiter of every bar and handstand skill. Hang, support and lean to build it.'}];
for(const g of MUS){g.list=M.filter(m=>g.re.test(m.muscles)).sort((a,b)=>a.diff-b.diff||a.name.localeCompare(b.name));if(!by[g.og])throw 'bad muscle og '+g.og;if(g.list.length<4)throw 'thin muscle '+g.id}
const GL=require('./glossary.js').map(([t,d,r])=>({t,id:slug(t),d,r:r.map(x=>{if(!by[x])throw 'bad glossary move '+x;return by[x]})}));
const VS=require('./vs.js').map(([a,b,wa,wb])=>{if(!by[a]||!by[b])throw 'bad vs '+a+' '+b;return{a:by[a],b:by[b],wa,wb,id:a+'-vs-'+b}});const vsOf=m=>VS.filter(v=>v.a==m||v.b==m);
const EQ=require('./equipment.js').map(([id,label,kw,og,why,sl])=>{if(!by[og])throw 'bad eq og '+og;return{id,label,kw,og,why,list:sl.map(x=>{if(!by[x])throw 'bad eq move '+x;return by[x]}).sort((a,b)=>a.diff-b.diff||a.name.localeCompare(b.name))}});
{const miss=M.filter(m=>!EQ.some(e=>e.list.includes(m)));if(miss.length)throw 'no equipment for '+miss.map(m=>m.slug)};
const eqOf=m=>EQ.filter(e=>e.list.includes(m));
const musOf=m=>MUS.filter(g=>g.list.includes(m));
for(const p of PLANS)p.steps=p.moves.map(x=>{if(!by[x])throw 'bad plan move '+x;return by[x]});
const faq=m=>{const p=plan(m),e=m.easier&&by[m.easier],h=m.harder&&by[m.harder];return[
 [`How hard is the ${m.name}?`,`The ${m.name} is Level ${m.diff}/10 (${m.tier} tier) in the Calisthenics Comics difficulty scale.`],
 [`What muscles does the ${m.name} work?`,`It mainly works: ${m.muscles}.`],
 [`Can you do the ${m.name} weighted?`,m.weighted?`Yes. Add load with: ${m.weightHow}. Only add weight once you can do ${p.goal.toLowerCase()} with perfect form.`:`Not practically — it's a bodyweight-only movement. Make it harder by moving to ${h?h.name:'stricter tempo and longer holds'}.`],
 [`What should I learn before the ${m.name}?`,e?`Build up with the ${e.name} (Level ${e.diff}) first.`:`It's a starting movement — no prerequisite needed.`],
 [`How many sets and reps of the ${m.name} should I do?`,`A good starting point at this level: ${p.scheme}, resting ${p.rest}, ${p.freq}. Move on when you can do ${p.goal.toLowerCase()}.`]]};

