 ld:[crumbLD([['Home','/'],['Skill roadmaps','/p/']]),{'@context':'https://schema.org','@type':'ItemList',itemListElement:ROADS.map((r,i)=>({'@type':'ListItem',position:i+1,url:`${SITE}/p/${r.g}/`,name:`${r.label} progression`}))}],
