 ld:[crumbLD([['Home','/'],['Workout plans','/w/']]),{'@context':'https://schema.org','@type':'ItemList',itemListElement:PLANS.map((p,i)=>({'@type':'ListItem',position:i+1,url:`${SITE}/w/${p.id}/`,name:`${p.label} calisthenics workout`}))}],
