const SD=[['push-up','Push-ups','reps',['5','15','30','45','60']],['pull-up','Pull-ups','reps',['1 (or 30 s hang)','5','12','20','30']],['parallel-bar-dip','Parallel-bar dips','reps',['1 (or 10 bench dips)','8','15','25','35']],['bodyweight-squat','Bodyweight squats','reps',['15','30','50','75','100']],['pistol-squat','Pistol squats (per leg)','reps',['Assisted 5','Assisted 10','3','8','15']],['plank','Plank','seconds',['30','60','120','180','300']],['hollow-body-hold','Hollow body hold','seconds',['10','30','60','90','120']],['l-sit','L-sit','seconds',['Tuck 5','Tuck 15','10','20','30']],['handstand-wall-hold','Wall handstand','seconds',['10','30','60','90','120']]];
const MS=[['Rookie','first full push-up and a 30-second dead hang','push-up'],['Brawler','first strict pull-up and dip','pull-up'],['Hero','an L-sit and a tuck front lever','l-sit'],['Champion','a muscle-up and a pistol squat','muscle-up'],['Titan','a full front lever or human flag','full-front-lever'],['Legend','the full planche','full-planche']];
