const intro=`# Calisthenics Comics\n\n> A comic-style encyclopedia of ${M.length} calisthenics (bodyweight) movements. Each move has a difficulty level 1–10, an XP tier (Rookie 1–2, Brawler 3–4, Hero 5–6, Champion 7–8, Titan 9, Legend 10), muscles worked, whether and how it can be weighted, a how-to, sets/reps by level, common mistakes and easier/harder progressions.\n\n`;
write('/llms.txt',intro+START_LLM+WARM_LLM+STD_LLM+`## Categories\n\n${Object.keys(CAT).map(c=>`- [${CAT[c][0]}](${SITE}/c/${c}/): ${CAT[c][2]}`).join('\n')}\n\n## Movements\n\n${M.map(m=>`- [${m.name}](${SITE}/m/${m.slug}/): Level ${m.diff} ${m.tier}, ${CAT[m.cat][0]}. ${m.muscles}.`).join('\n')}\n\n## Skill roadmaps\n\n${ROADS.map(r=>`- [${r.label} progression](${SITE}/p/${r.g}/): ${r.steps.map(x=>x.name).join(' → ')}.`).join('\n')}\n\n## Workout plans\n\n${PLANS.map(p=>`- [${p.label} workout (${p.band})](${SITE}/w/${p.id}/): ${p.days}; ${p.steps.map(x=>x.name).join(', ')}.`).join('\n')}\n\n## Exercises by muscle\n\n${MUS.map(g=>`- [${g.label} exercises](${SITE}/muscles/${g.id}/): ${g.list.length} moves, ${g.list.map(x=>x.name).join(', ')}.`).join('\n')}\n\n## Exercises by level\n\n${LV.map(v=>`- [${v.kw} exercises, ${v.t} tier (${v.band})](${SITE}/levels/${v.id}/): ${v.list.map(x=>x.name).join(", ")}.`).join("\n")}\n\n## Exercises by equipment\n\n${EQ.map(e=>`- [${e.kw} calisthenics exercises](${SITE}/equipment/${e.id}/): ${e.list.map(x=>x.name).join(", ")}.`).join("\n")}\n\n## Exercise comparisons\n\n${VS.map(v=>`- [${v.a.name} vs ${v.b.name}](${SITE}/vs/${v.id}/): Level ${v.a.diff} vs ${v.b.diff}. Pick ${v.a.name} if ${v.wa}; pick ${v.b.name} if ${v.wb}.`).join('\n')}\n\n## Glossary\n\n${GL.map(g=>`- [${g.t}](${SITE}/glossary/#${g.id}): ${g.d}`).join('\n')}\n\n## Optional\n\n- [Full content in one file](${SITE}/llms-full.txt)\n- [Structured JSON dataset of every move](${SITE}/moves.json)\n- [Sitemap](${SITE}/sitemap.xml)\n`);
write('/llms-full.txt',intro+M.map(m=>{const p=plan(m);return `## ${m.name}\n\nURL: ${SITE}/m/${m.slug}/\n- Category: ${CAT[m.cat][0]}\n- Difficulty: ${m.diff}/10 (${m.tier})\n- Muscles: ${m.muscles}\n- Type: ${HOLDS.has(m.slug)?'isometric hold':'dynamic reps'}\n- Weighted: ${m.weighted?'yes — '+m.weightHow:'no'}\n- How to: ${m.how}\n- Sets/reps: ${p.scheme}, rest ${p.rest}, ${p.freq}. Level-up goal: ${p.goal}.\n- Easier: ${m.easier?by[m.easier].name:'—'}\n- Harder: ${m.harder?by[m.harder].name:'—'}\n- Common mistakes: ${MIST[m.cat].join(' ')}\n`}).join('\n')+'\n'+PLANS.map(p=>`## ${p.label} workout plan (${p.band})\n\nURL: ${SITE}/w/${p.id}/\n- Who: ${p.who}\n- Frequency: ${p.days}; ${p.time}\n- Warm-up: ${WARM}\n${p.steps.map((x,j)=>`- ${j+1}. ${x.name}: ${plan(x).scheme}, rest ${plan(x).rest}`).join('\n')}\n- Level-up test: ${p.next}\n`).join('\n'));
